import { Component, inject, signal, computed, OnInit, effect } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { ReactiveFormsModule, NonNullableFormBuilder, Validators } from '@angular/forms';
import { TramiteService } from '../../../../../shared/services/tramite.service';
import { TramitePayload, ModalidadValue, NivelGobiernoValue, OpcionesCatalogo } from '../../../../../shared/models/tramite.model';
import { ChipInputComponent } from '../../../../../shared/components/chip-input/chip-input.component';
import { extractErrorMessage } from '../../../../../shared/utils/error-utils';

const MODALIDAD_LABELS: Record<string, string> = {
  presencial: 'Presencial',
  en_linea: 'En línea',
};

const NIVEL_LABELS: Record<string, string> = {
  estatal: 'Estatal',
  municipal: 'Municipal',
  federal: 'Federal',
};

const ETAPA_LABELS: Record<string, string> = {
  pre_inversion: 'Pre-inversión',
  construccion: 'Construcción',
  operacion: 'Operación',
  ampliacion: 'Ampliación',
};

@Component({
  selector: 'app-tramite-form',
  imports: [ReactiveFormsModule, ChipInputComponent],
  templateUrl: './tramite-form.component.html',
})
export class TramiteFormComponent implements OnInit {
  private readonly fb = inject(NonNullableFormBuilder);
  private readonly tramiteService = inject(TramiteService);
  private readonly route = inject(ActivatedRoute);
  private readonly router = inject(Router);

  protected readonly isEditMode = signal(false);
  protected readonly tramiteId = signal<number | null>(null);
  protected readonly submitting = signal(false);
  protected readonly error = signal('');
  protected readonly opciones = signal<OpcionesCatalogo>({ etapas: [], nivelesGobierno: [], modalidadesCanal: [] });
  protected readonly chipItems = signal<string[]>([]);
  protected readonly canales = signal<ModalidadValue[]>(['presencial']);

  protected readonly modalidadOptions = computed(() =>
    this.opciones().modalidadesCanal.map(v => ({ value: v as ModalidadValue, label: MODALIDAD_LABELS[v] ?? v })),
  );

  protected readonly nivelOptions = computed(() =>
    this.opciones().nivelesGobierno.map(v => ({ value: v, label: NIVEL_LABELS[v] ?? v })),
  );

  protected readonly etapaOptions = computed(() =>
    this.opciones().etapas.map(v => ({ value: v, label: ETAPA_LABELS[v] ?? v })),
  );

  protected readonly form = this.fb.group({
    nombre: ['', Validators.required],
    descripcion: ['', Validators.required],
    link: [''],
    nivelGobierno: ['estatal' as NivelGobiernoValue, Validators.required],
    etapa: [''],
    vigenciaDias: ['', [Validators.min(1), Validators.max(365)]],
  });

  private readonly linkValidationEffect = effect(() => this.updateLinkValidation());

  ngOnInit(): void {
    this.loadOpciones();
    const id = this.route.snapshot.paramMap.get('id');
    if (id) {
      this.isEditMode.set(true);
      this.tramiteId.set(Number(id));
      this.loadTramite(Number(id));
    }
  }

  private loadOpciones(): void {
    this.tramiteService.getOpciones().subscribe(opciones => {
      this.opciones.set(opciones);
    });
  }

  private loadTramite(id: number): void {
    this.tramiteService.getTramite(id).subscribe(tramite => {
      this.form.patchValue({
        nombre: tramite.nombre,
        descripcion: tramite.descripcion,
        link: tramite.link ?? '',
        nivelGobierno: tramite.nivelGobierno,
        etapa: tramite.etapa ?? '',
        vigenciaDias: tramite.vigenciaDias?.toString() ?? '',
      });
      this.canales.set(tramite.modalidad);
      this.chipItems.set([...tramite.modalidades]);
      this.form.updateValueAndValidity();
    });
  }

  private updateLinkValidation(): void {
    const linkControl = this.form.controls.link;
    if (this.canales().includes('en_linea')) {
      linkControl.setValidators([Validators.required, Validators.pattern(/^https?:\/\/.+/)]);
    } else {
      linkControl.clearValidators();
      linkControl.setValue('');
    }
    linkControl.updateValueAndValidity();
  }

  protected onChipItemsChange(items: string[]): void {
    this.chipItems.set(items);
  }

  protected onCanalToggle(value: ModalidadValue): void {
    const current = this.canales();
    if (current.includes(value)) {
      if (current.length > 1) {
        this.canales.set(current.filter(c => c !== value));
      }
    } else {
      this.canales.set([...current, value]);
    }
  }

  protected onSubmit(): void {
    if (this.form.invalid || this.chipItems().length === 0) {
      this.form.markAllAsTouched();
      if (this.chipItems().length === 0) {
        this.error.set('Agrega al menos una modalidad de atención.');
      }
      return;
    }

    this.submitting.set(true);
    this.error.set('');

    const formValue = this.form.getRawValue();
    const payload: TramitePayload = {
      nombre: formValue.nombre,
      descripcion: formValue.descripcion,
      modalidad: this.canales(),
      modalidades: this.chipItems(),
      link: this.canales().includes('en_linea') ? formValue.link : null,
      nivelGobierno: formValue.nivelGobierno,
      etapa: formValue.etapa || null,
      vigenciaDias: formValue.vigenciaDias ? Number(formValue.vigenciaDias) : null,
    };

    const operation = this.isEditMode()
      ? this.tramiteService.updateTramite(this.tramiteId()!, payload)
      : this.tramiteService.createTramite(payload);

    operation.subscribe({
      next: () => {
        this.submitting.set(false);
        this.router.navigate(['/ejecutivos/configuracion/tramites']);
      },
      error: (err) => {
        this.submitting.set(false);
        this.error.set(extractErrorMessage(err));
      },
    });
  }

  protected onCancel(): void {
    this.router.navigate(['/ejecutivos/configuracion/tramites']);
  }
}
