import { Component, input, output, signal } from '@angular/core';

@Component({
  selector: 'app-chip-input',
  templateUrl: './chip-input.component.html',
  styleUrl: './chip-input.component.scss',
})
export class ChipInputComponent {
  readonly items = input<string[]>([]);
  readonly itemsChange = output<string[]>();
  readonly placeholder = input<string>('');
  readonly label = input<string>('');

  protected readonly inputValue = signal('');

  onInput(event: Event): void {
    this.inputValue.set((event.target as HTMLInputElement).value);
  }

  addChip(event: KeyboardEvent): void {
    if (event.key !== 'Enter') return;
    event.preventDefault();

    const value = this.inputValue().trim();
    if (!value) return;

    const lowercased = value.toLowerCase();
    const exists = this.items().some(item => item.toLowerCase() === lowercased);
    if (exists) {
      this.inputValue.set('');
      return;
    }

    this.itemsChange.emit([...this.items(), value]);
    this.inputValue.set('');
  }

  removeChip(index: number): void {
    const updated = this.items().filter((_, i) => i !== index);
    this.itemsChange.emit(updated);
  }

  onKeydown(event: Event): void {
    if (event instanceof KeyboardEvent && event.key === 'Backspace' && this.inputValue() === '' && this.items().length > 0) {
      this.removeChip(this.items().length - 1);
    }
  }
}
